      es: ["Un estratovolcán extremadamente activo y con varios glaciares cerca del valle del Colca, que emite frecuentemente nubes de ceniza.", "Situado en el territorio de la República del Perú.", "Integrada entre la cordillera de los Andes, el desierto costero y la cuenca del Amazonas.", "Desempeña un papel en la identidad local de la región.", "Conocida por su importancia paisajística o cultural."],
