    description: {
      de: "Ein ruhender, eisbedeckter Vulkan in den Anden, auf dem 1995 die berühmte Inka-Eismumie 'Juanita' gefunden wurde.",
      hu: "Szunnyadó, jéggel borított vulkán az Andokban, ahol 1995-ben megtalálták 'Juanita', a híres inka jégmúmia maradványait.",
      ro: "Un vulcan adormit, acoperit de gheață din Anzi, unde în 1995 a fost descoperită celebra mumie incașă 'Juanita'.",
      en: "A dormant, ice-capped volcano in the Andes where the famous Inca ice mummy 'Juanita' was discovered in 1995.",
      es: "Un volcán inactivo cubierto de hielo en los Andes, donde en 1995 se encontró a la famosa momia inca 'Juanita'.",
      pt: "Um vulcão adormecido coberto de gelo nos Andes, onde em 1995 foi encontrada a famosa múmia inca 'Juanita'.",
      fr: "Un volcan endormi couvert de glace dans les Andes, où la célèbre momie inca 'Juanita' a été découverte en 1995.",
    },
    descriptionAdvanced: {
      de: "Der Mount Ampato ist ein inaktiver Stratovulkan in den peruanischen Anden mit einer Höhe von 6.288 Metern. Er gehört zum Ampato-Vulkankomplex in der Region Arequipa und ist weltweit vor allem für eine bedeutende archäologische Entdeckung bekannt. Im Jahr 1995 fand der Anthropologe Johan Reinhard nahe dem Gipfel die mumifizierten Überreste eines Inka-Mädchens, das als „Juanita“ oder „Eismädchen von Ampato“ bekannt wurde. Der Fund belegte die Praxis von rituellen Opfern (Capacocha) auf den höchsten Gipfeln der Anden. Geologisch ist der Ampato ein massives Gebilde, dessen schneebedeckte Flanken durch die Hitze des benachbarten aktiven Vulkans Sabancaya teilweise schmelzen. Die Besteigung des Berges ist aufgrund der extremen Höhe und der klimatischen Bedingungen eine Herausforderung, wird aber häufig mit Expeditionen zum Studium der Inka-Heiligtümer kombiniert.",
      hu: "Az Ampato egy 6288 méter magas kialvó sztratovulkán Peru déli részén, az Arequipa régióban. A hegy nemzetközi hírnevét elsősorban egy 1995-ben történt szenzációs régészeti felfedezésnek köszönheti: ekkor találták meg a csúcs közelében „Juanitát”, az inka jéglányt. A tökéletesen konzerválódott múmia egy rituális inka áldozat (Capacocha) emlékét őrzi, amelyet több mint 500 évvel ezelőtt mutattak be a hegyi istenek tiszteletére. A felfedezést a szomszédos Sabancaya vulkán kitörése tette lehetővé, amelynek hamuja megolvasztotta az Ampato jégsapkáját, feltárva a sírhelyet. Geológiailag a hegy az Ampato-Sabancaya-Hualca Hualca vulkáni lánc része. A hegycsúcs elérése komoly fizikai felkészültséget igényel az oxigénhiány és a meredek, jeges terep miatt, de a történelmi jelentősége miatt a kutatók és hegymászók egyik kedvelt célpontja.",
      ro: "Muntele Ampato este un stratovulcan inactiv situat în Anzii peruvieni, atingând o altitudine de 6.288 de metri. Acesta face parte din lanțul vulcanic Ampato-Sabancaya-Hualca Hualca din regiunea Arequipa. Muntele a devenit faimos la nivel mondial în 1995, când antropologul Johan Reinhard a descoperit în apropierea vârfului corpul conservat al unei fete incașe, cunoscută sub numele de „Mumia Juanita”. Această descoperire a oferit dovezi cruciale despre ritualurile de sacrificiu uman, numite Capacocha, practicate de Imperiul Inca pe vârfurile munților sacri. Topirea parțială a calotei glaciare a muntelui, cauzată de cenușa fierbinte a vulcanului vecin Sabancaya, a facilitat găsirea vestigiilor. Ampato rămâne un sit de o importanță arheologică și geologică imensă, fiind o destinație majoră pentru expedițiile de înaltă altitudine care îmbină alpinismul cu studiul istoriei andine.",
      en: "Mount Ampato is a dormant stratovolcano in the Peruvian Andes, rising to an elevation of 6,288 meters above sea level. Located in the Arequipa region, it forms part of a volcanic trio alongside Sabancaya and Hualca Hualca. The mountain gained global fame in 1995 following the discovery of 'Juanita, the Ice Maiden,' a well-preserved Inca mummy found near the summit by archaeologist Johan Reinhard. This finding confirmed the Inca practice of high-altitude human sacrifice, or Capacocha, intended to appease mountain deities. The mummy was exposed when ash from the nearby erupting Sabancaya caused the glacial ice on Ampato to melt. Today, Ampato serves as a significant site for both glaciological research and mountaineering, offering insights into ancient Andean religious traditions and the impacts of climate change on high-altitude tropical glaciers.",
      es: "El Ampato es un elemento notable de la geografía y cultura peruana. Es un volcán inactivo donde se halló a 'Juanita', la momia de los hielos. Se eleva a 6.288 metros y forma parte de la Cordillera Ampato, marcando la topografía de Perú entre los Andes y el Amazonas. Como muchos lugares importantes en Perú, este sitio combina misterios regionales con una importancia global por su valor arqueológico. Así, contribuye al perfil polifacético del país, desde el legado inca y Machu Picchu hasta las altas cumbres nevadas de la cordillera andina.",
      pt: "O Ampato é um elemento notável da geografia e cultura peruana. É um vulcão adormecido onde foi encontrada 'Juanita', a múmia dos gelos. Eleva-se a 6.288 metros e faz parte da Cordilheira Ampato, marcando a topografia do Peru entre os Andes e a Amazônia. Como muitos lugares importantes no Peru, este local combina mistérios regionais com uma importância global pelo seu valor arqueológico. Assim, contribui para o perfil multifacetado do país, desde a herança inca e Machu Picchu até aos altos cumes nevados da cordilheira andina.",
      fr: "L'Ampato est un élément remarquable de la géographie et de la culture péruviennes. Ce volcan endormi est le lieu de découverte de 'Juanita', la momie des glaces. Culminant à 6 288 mètres dans la cordillère Ampato, il forge la topographie du Pérou entre les Andes et l'Amazonie. Comme de nombreux sites majeurs au Pérou, ce lieu allie mystères régionaux et importance globale pour l'archéologie. Il participe ainsi au profil varié du pays, de l'héritage inca et du Machu Picchu aux hauts sommets enneigés de la chaîne andine.",
    },
