      de: ["Höchster Vulkan Perus mit 6.377 m", "Besitzt die größte tropische Eiskappe der Welt", "Besteht aus sechs verschiedenen Gipfeln", "Heiligster Berg (Apu) der südlichen Inka-Region", "Eisfläche ist seit 1955 um über 50 % geschrumpft", "Etwa 150 km nordwestlich von Arequipa"],
      hu: ["Peru legmagasabb vulkánja (6377 m)", "A világ legnagyobb trópusi jégsapkája borítja", "Hat különálló csúccsal rendelkezik", "Az inka birodalom egyik legfontosabb szent hegye", "Jégfelülete 1955 óta több mint felére csökkent", "Arequipától 150 km-re északnyugatra található"],
      ro: ["Cel mai înalt vulcan din Peru (6.377 m)", "Deține cea mai mare calotă glaciară tropicală", "Compus din șase vârfuri distincte", "Munte sacru major (Apu) în timpul incașilor", "Suprafața ghețarului s-a redus cu 50% din 1955", "Situat la 150 km nord-vest de Arequipa"],
      en: ["Highest volcano in Peru at 6,377 meters", "Hosts the largest tropical ice cap on Earth", "Consists of six separate summit peaks", "Major sacred mountain (Apu) for the Inca", "Glacial area has shrunk by over 50% since 1955", "Located 150 km northwest of Arequipa"],
      es: ["El volcán más alto del Perú y la tercera montaña más alta del país, coronado por un enorme casquete de hielo.", "Situado en el territorio de la República del Perú.", "Inmerso entre la Cordillera de los Andes, el desierto costero y la cuenca amazónica.", "Juega un papel en la identidad local de la región.", "Conocido por su importancia paisajística o cultural."],
      pt: ["O vulcão mais alto do Peru e a terceira montanha mais alta do país, coroado por uma enorme calota de gelo.", "Localizado no território da República do Peru.", "Inserido entre a Cordilheira dos Andes, o deserto costeiro e a bacia amazônica.", "Desempenha um papel na identidade local da região.", "Conhecido pela sua importância paisagística ou cultural."],
      fr: ["Le plus haut volcan du Pérou et la troisième plus haute montagne du pays, couronné par une immense calotte glaciaire.", "Situé sur le territoire de la République du Pérou.", "Nichée entre la cordillère des Andes, le désert côtier et le bassin amazonien.", "Joue un rôle dans l'identité locale de la région.", "Connu pour son importance paysagère ou culturelle."],
