      hu: ["Csúcsmagassága 6057 méter", "Négy fő csúcsból épül fel", "A világ legkönnyebb hatezresének tartják", "Arequipa fehér köveinek egyik forrása", "A rendkívül száraz levegő miatt kevés rajta a hó", "Mindössze 22 km-re fekszik Arequipától"],
