    description: {
      de: "Ein spektakuläres, kompakt Hochgebirge, das bei Trekkern und Bergsteigern weltweit für seine steilen Felswände geschätzt wird.",
      hu: "Látványos, kompakt magashegység, amelyet a túrázók és hegymászók világszerte meredek sziklafalai miatt kedvelnek.",
      ro: "Un lanț muntos spectaculos și compact, apreciat la nivel mondial de amatorii de drumeții și alpiniști pentru pereții săi stâncoși abrupți.",
      en: "A spectacular, compact high mountain range cherished globally by trekkers and mountaineers for its steep rock faces.",
      es: "Una espectacular y compacta cordillera de alta montaña, apreciada mundialmente por excursionistas y alpinistas por sus escarpadas paredes rocosas.",
      pt: "Uma cordilheira de alta montanha espetacular e compacta, apreciada mundialmente por trekkers e alpinistas pelas suas paredes rochosas íngremes.",
      fr: "Une chaîne de haute montagne spectaculaire et compacte, prisée mondialement par les randonneurs et alpinistes pour ses parois rocheuses abruptes.",
    },
    descriptionAdvanced: {
      de: "Die Cordillera Huayhuash ist eine kompakte, aber dramatische Gebirgskette in den peruanischen Anden, südlich der Cordillera Blanca. Trotz ihrer geringen Länge von nur etwa 30 Kilometern beherbergt sie einige der spektakulärsten und technisch anspruchsvollsten Gipfel Perus, darunter den Yerupajá, der mit 6.634 Metern der zweithöchste Berg des Landes ist. Die Kette ist berühmt für ihre steilen Eiswände und scharfen Grate, die sie zu einem Mekka für Extrembergsteiger machen. Internationale Bekanntheit erlangte die Region auch durch das Buch und den Film „Touching the Void“, die den Überlebenskampf von Joe Simpson am Siula Grande schildern. Die Wanderung um das Huayhuash-Massiv gilt als eine der schönsten und anstrengendsten Trekkingtouren der Welt. Geographisch bildet das Gebirge die Grenze zwischen den Regionen Ancash, Lima und Huánuco und ist Teil der kontinentalen Wasserscheide.",
      hu: "A Cordillera Huayhuash egy viszonylag rövid, mindössze 30 kilométer hosszan elnyúló, de rendkívül látványos hegylánc Peru középső részén, a Cordillera Blancától délre. Itt található Peru második legmagasabb csúcsa, a 6634 méteres Yerupajá, amely technikai nehézségei miatt a világ egyik legnehezebben megmászható hegyeként ismert. A hegység híres meredek jégfalairól, éles gerinceiről és türkizkék tengerszemeiről. A terület világhírnevét Joe Simpson „Zuhanás a csendbe” című könyve és az abból készült film is növelte, amely a Siula Grande csúcsán történt drámai eseményeket dolgozza fel. A Huayhuash-körút a világ egyik legszebb, de egyben legmegterhelőbb magashegyi túraútvonala, amely során több 4500-5000 méter magas hágón kell átkelni. A hegység elszigeteltsége és vadregényes tájai egyedülálló élményt nyújtanak a látogatóknak, távol a tömegturizmustól.",
      ro: "Cordillera Huayhuash este un lanț muntos compact și spectaculos situat în Anzii peruvieni, la sud de Cordillera Blanca. Deși se întinde pe o lungime de doar 30 de kilometri, acesta concentrează unele dintre cele mai înalte și tehnice vârfuri din Peru, inclusiv Yerupajá, care la 6.634 de metri este al doilea cel mai înalt munte din țară. Regiunea este renumită pentru pereții săi verticali de gheață și crestele ascuțite, fiind considerată o provocare extremă chiar și pentru alpiniștii experimentați. Faima internațională a crescut odată cu relatarea supraviețuirii miraculoase a lui Joe Simpson pe muntele Siula Grande. Traseul de trekking care înconjoară masivul este recunoscut constant ca fiind unul dintre cele mai frumoase din lume, oferind panorame glaciare de neegalat. Cordillera Huayhuash servește ca un nod hidrografic important, alimentând bazinele care se varsă atât în Oceanul Pacific, cât și în fluviul Amazon.",
      en: "The Cordillera Huayhuash is a compact yet exceptionally rugged mountain range in the Peruvian Andes, located south of the Cordillera Blanca. Spanning only about 30 kilometers from north to south, it features some of Peru's most formidable peaks, including Yerupajá, the country's second-highest mountain at 6,634 meters. The range is characterized by sharp, jagged ridges and near-vertical ice faces, earning it a reputation as one of the most challenging regions for mountaineering. It gained international notoriety through the story of Joe Simpson's survival on Siula Grande, detailed in the book and film 'Touching the Void.' The Huayhuash Circuit is widely considered one of the premier high-altitude trekking routes globally, crossing multiple passes over 4,500 meters. The range marks the convergence of the Ancash, Lima, and Huánuco regions and remains a vital protected area for Andean biodiversity and glacial water resources.",
      es: "La Cordillera Huayhuash es un elemento notable de la geografía y cultura peruana. Una espectacular y compacta cordillera de alta montaña, apreciada mundialmente por senderistas y alpinistas por sus paredes escarpadas. Ruta de trekking popular. Alberga la montaña Yerupajá. Esta formación geográfica marca la topografía de Perú a lo largo de la Cordillera de los Andes, el desierto costero y la cuenca amazónica. Al igual que muchos lugares importantes de Perú, este sitio combina peculiaridades regionales entre el Pacífico, los Andes y la Amazonía con una importancia global. Así, este lugar contribuye al perfil diverso de Perú, desde la herencia inca y Machu Picchu hasta Lima y la cuenca del Amazonas.",
      pt: "A Cordilheira Huayhuash é um elemento notável da geografia e cultura peruana. Uma cordilheira de alta montanha espetacular e compacta, apreciada mundialmente por trekkers e alpinistas pelas suas paredes íngremes. Rota de trekking popular. Abriga a montanha Yerupajá. Esta forma de relevo molda a topografia do Peru ao longo da Cordilheira dos Andes, do deserto costeiro e da bacia amazônica. Como muitos locais importantes no Peru, este local combina peculiaridades regionais entre o Pacífico, os Andes e a Amazônia com uma importância abrangente. Assim, este local contribui para o perfil diversificado do Peru, desde a herança inca e Machu Picchu até Lima e a bacia amazônica.",
      fr: "La Cordillère Huayhuash est un élément remarquable de la géographie et de la culture péruviennes. Un massif de haute montagne spectaculaire et compact, estimé par les trekkeurs et alpinistes du monde entier pour ses faces abruptes. Itinéraire de randonnée populaire. Abrite le mont Yerupajá. Cette forme de relief façonne la topographie du Pérou le long de la cordillère des Andes, du désert côtier et du bassin amazonien. Comme de nombreux sites importants au Pérou, ce lieu combine des particularités régionales entre le Pacifique, les Andes et l'Amazonie avec une importance globale. Ainsi, ce lieu contribue au profil diversifié du Pérou, de l'héritage inca et du Machu Picchu à Lima et au bassin amazonien.",
    },
