      ro: ["Găzduiește vârful Yerupajá (6.634 m)", "Lungimea totală a lanțului este de doar 30 km", "Locul evenimentelor din „Touching the Void”", "Cuprinde șapte vârfuri de peste 6.000 m", "Circuitul Huayhuash este un traseu de trekking de top", "Situat la intersecția a trei regiuni administrative"],
