      es: ["Una espectacular y compacta cordillera de alta montaña, apreciada mundialmente por excursionistas y alpinistas por sus escarpadas paredes rocosas.", "Situado en el territorio de la República del Perú.", "Inmerso entre la Cordillera de los Andes, el desierto costero y la cuenca amazónica.", "Juega un papel en la identidad local de la región.", "Conocido por su importancia paisajística o cultural."],
      pt: ["Uma cordilheira de alta montanha espetacular e compacta, apreciada mundialmente por trekkers e alpinistas pelas suas paredes rochosas íngremes.", "Localizado no território da República do Peru.", "Inserido entre a Cordilheira dos Andes, o deserto costeiro e a bacia amazônica.", "Desempenha um papel na identidade local da região.", "Conhecido pela sua importância paisagística ou cultural."],
      fr: ["Une chaîne de haute montagne spectaculaire et compacte, prisée mondialement par les randonneurs et alpinistes pour ses parois rocheuses abruptes.", "Situé sur le territoire de la République du Pérou.", "Nichée entre la cordillère des Andes, le désert côtier et le bassin amazonien.", "Joue un rôle dans l'identité locale de la région.", "Connu pour son importance paysagère ou culturelle."],
