      hu: ["Az Artesonraju csúcsa pontosan 6025 méter magasan található.", "Jellegzetes piramis alakja szolgált a Paramount Pictures logójának mintájául.", "A hegyet először 1932. augusztus 19-én mászták meg.", "A hegy az Ancash régióban található Huascarán Nemzeti Park része.", "A csúcsoldalak dőlésszöge átlagosan 50 fokos.", "A hegy lábánál fekszik a hatalmas Laguna Parón gleccsertó."],
