      en: ["Artesonraju has a summit elevation of exactly 6,025 meters.", "Its iconic pyramidal shape served as the model for the Paramount Pictures logo.", "The first recorded ascent took place on August 19, 1932.", "The mountain is part of the Huascarán National Park in the Ancash region.", "The steepness of its summit flanks averages around 50 degrees.", "The large glacial lake Laguna Parón is situated at the base of the mountain."],
